30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
40	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
41	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
42	import org.springframework.samples.petclinic.rest.validation.IdentityNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
111	        owner.setTelephone(telephone);
112	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
113	        if (owner.getRegistrationDate() == null) {
114	            owner.setRegistrationDate(LocalDate.now());
115	        }
116	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
117	            .anyMatch(existing -> telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone())));
118	        if (telephoneInUse) {
119	            throw new DuplicateTelephoneException(
120	                "telephone " + telephone + " is already used by another owner");
121	        }
122	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
123	            String lastName = IdentityNormalizer.normalize(owner.getLastName());
124	            String address = IdentityNormalizer.normalize(owner.getAddress());
125	            boolean householdInUse = this.clinicService.findAllOwners().stream()
126	                .anyMatch(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
127	                    && address.equals(IdentityNormalizer.normalize(existing.getAddress())));
128	            if (householdInUse) {
129	                throw new DuplicateHouseholdException(
130	                    "an owner with last name " + owner.getLastName() + " already lives at " + owner.getAddress());
131	            }
132	        }
133	        this.clinicService.createOwner(owner);
134	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
143	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
144	        if (currentOwner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        currentOwner.setAddress(ownerFieldsDto.getAddress());
148	        currentOwner.setCity(ownerFieldsDto.getCity());
149	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
150	        currentOwner.setLastName(ownerFieldsDto.getLastName());
151	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
152	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
153	        this.clinicService.saveOwner(currentOwner);
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Transactional
159	    @Override
160	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        this.clinicService.deleteOwner(owner);
166	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        HttpHeaders headers = new HttpHeaders();
177	        Pet pet = petMapper.toPet(petFieldsDto);
178	        owner.setId(ownerId);
179	        pet.setOwner(owner);
180	        pet.getType().setName(null);
181	        this.clinicService.savePet(pet);
182	        PetDto petDto = petMapper.toPetDto(pet);
183	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
184	            .buildAndExpand(pet.getId()).toUri());
185	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
191	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
192	        if (currentOwner != null) {
193	            Pet currentPet = this.clinicService.findPetById(petId);
194	            if (currentPet != null) {
195	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
196	                currentPet.setName(petFieldsDto.getName());
197	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
198	                this.clinicService.savePet(currentPet);
199	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	            }
201	        }
202	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
208	        HttpHeaders headers = new HttpHeaders();
209	        Visit visit = visitMapper.toVisit(visitFieldsDto);
210	        Pet pet = new Pet();
211	        pet.setId(petId);
212	        visit.setPet(pet);
213	        this.clinicService.saveVisit(visit);
214	        VisitDto visitDto = visitMapper.toVisitDto(visit);
215	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
216	            .buildAndExpand(visit.getId()).toUri());
217	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
218	    }
219	
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner != null) {
226	            Pet pet = owner.getPet(petId);
227	            if (pet != null) {
228	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
229	            }
230	        }
231	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	    }
233	}
