212	     *
213	     * @param e The {@link MethodArgumentNotValidException} to be handled
214	     * @param request {@link HttpServletRequest} object referring to the current request.
215	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
216	     */
217	    @ExceptionHandler(MethodArgumentNotValidException.class)
218	    @ResponseBody
219	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
220	        HttpStatus status = HttpStatus.BAD_REQUEST;
221	        BindingErrorsResponse errors = new BindingErrorsResponse();
222	        BindingResult bindingResult = e.getBindingResult();
223	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
224	        if (bindingResult.hasErrors()) {
225	            errors.addAllErrors(bindingResult);
226	            List<String> errorFields = bindingResult.getFieldErrors().stream()
227	                .map(fieldError -> fieldError.getField())
228	                .distinct()
229	                .toList();
230	            detail.setProperty("errors", errorFields);
231	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
232	                .map(fieldError -> {
233	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
234	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
235	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
236	                        fieldError.getField(),
237	                        defaultMessage,
238	                        rejectedValue);
239	                    return new ValidationMessageDto(message)
240	                        .putAdditionalProperty("field", fieldError.getField())
241	                        .putAdditionalProperty("rejectedValue", rejectedValue)
242	                        .putAdditionalProperty("defaultMessage", defaultMessage);
243	                })
244	                .toList();
245	            logger.debug("Validation error at {} {}: {}",
246	                request.getMethod(),
247	                request.getRequestURI(),
248	                bindingResult.getFieldErrors());
249	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
250	            return ResponseEntity.status(status).body(detail);
251	        }
252	        return ResponseEntity.status(status).body(detail);
